statements:
CREATE TABLE IF NOT EXISTS tenant_state (
  tenant_id text PRIMARY KEY,
  revision bigint NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS knowledge_bases (
  tenant_id text NOT NULL,
  kb_id text NOT NULL,
  name text NOT NULL,
  owner_id text NOT NULL,
  revision bigint NOT NULL DEFAULT 0,
  manifest_id text,
  PRIMARY KEY (tenant_id, kb_id)
);
CREATE TABLE IF NOT EXISTS members (
  tenant_id text NOT NULL,
  kb_id text NOT NULL,
  principal_id text NOT NULL,
  capabilities jsonb NOT NULL,
  PRIMARY KEY (tenant_id, kb_id, principal_id),
  FOREIGN KEY (tenant_id, kb_id) REFERENCES knowledge_bases (tenant_id, kb_id)
);
CREATE TABLE IF NOT EXISTS sources (
  tenant_id text NOT NULL,
  source_id text NOT NULL,
  owner_id text NOT NULL,
  readers jsonb NOT NULL,
  policy jsonb NOT NULL,
  revision bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (tenant_id, source_id)
);
CREATE TABLE IF NOT EXISTS source_versions (
  tenant_id text NOT NULL,
  source_id text NOT NULL,
  source_version_id text NOT NULL,
  filename text NOT NULL,
  original_path text NOT NULL,
  original_sha256 text NOT NULL,
  media_type text NOT NULL,
  PRIMARY KEY (tenant_id, source_id, source_version_id),
  FOREIGN KEY (tenant_id, source_id) REFERENCES sources (tenant_id, source_id)
);
CREATE TABLE IF NOT EXISTS parse_snapshots (
  tenant_id text NOT NULL,
  source_id text NOT NULL,
  source_version_id text NOT NULL,
  parse_snapshot_id text NOT NULL,
  document jsonb NOT NULL,
  PRIMARY KEY (tenant_id, source_id, source_version_id, parse_snapshot_id),
  FOREIGN KEY (tenant_id, source_id, source_version_id)
    REFERENCES source_versions (tenant_id, source_id, source_version_id)
);
CREATE TABLE IF NOT EXISTS bindings (
  tenant_id text NOT NULL,
  kb_id text NOT NULL,
  binding_id text NOT NULL,
  source_id text NOT NULL,
  source_version_id text NOT NULL,
  parse_snapshot_id text NOT NULL,
  status text NOT NULL CHECK (status IN ('ACTIVE', 'REMOVED', 'SUSPENDED')),
  revision bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (tenant_id, kb_id, binding_id),
  UNIQUE (tenant_id, kb_id, source_id),
  FOREIGN KEY (tenant_id, kb_id) REFERENCES knowledge_bases (tenant_id, kb_id),
  FOREIGN KEY (tenant_id, source_id, source_version_id, parse_snapshot_id)
    REFERENCES parse_snapshots (tenant_id, source_id, source_version_id, parse_snapshot_id)
);
CREATE TABLE IF NOT EXISTS builds (
  tenant_id text NOT NULL,
  kb_id text NOT NULL,
  build_id text NOT NULL,
  expected_manifest_id text,
  authority_revision bigint NOT NULL,
  kb_revision bigint NOT NULL,
  index_name text NOT NULL,
  inputs jsonb NOT NULL,
  status text NOT NULL CHECK (status IN ('STAGING', 'VALIDATED', 'PUBLISHED', 'FAILED')),
  unit_count integer NOT NULL,
  PRIMARY KEY (tenant_id, kb_id, build_id),
  FOREIGN KEY (tenant_id, kb_id) REFERENCES knowledge_bases (tenant_id, kb_id)
);
CREATE TABLE IF NOT EXISTS citations (
  tenant_id text NOT NULL,
  kb_id text NOT NULL,
  citation_id text NOT NULL,
  build_id text NOT NULL,
  binding_id text NOT NULL,
  source_id text NOT NULL,
  source_version_id text NOT NULL,
  parse_snapshot_id text NOT NULL,
  element_id text NOT NULL,
  text text NOT NULL,
  evidence_ids jsonb NOT NULL,
  anchors jsonb NOT NULL,
  table_data jsonb,
  PRIMARY KEY (tenant_id, kb_id, citation_id),
  FOREIGN KEY (tenant_id, kb_id, build_id) REFERENCES builds (tenant_id, kb_id, build_id),
  FOREIGN KEY (tenant_id, kb_id, binding_id) REFERENCES bindings (tenant_id, kb_id, binding_id),
  FOREIGN KEY (tenant_id, source_id, source_version_id, parse_snapshot_id)
    REFERENCES parse_snapshots (tenant_id, source_id, source_version_id, parse_snapshot_id)
);

DO $$ DECLARE name text; BEGIN
  FOREACH name IN ARRAY ARRAY['tenant_state','knowledge_bases','members','sources','source_versions','parse_snapshots'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', name);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', name);
    EXECUTE format('DROP POLICY IF EXISTS tenant_scope ON %I', name);
    EXECUTE format('CREATE POLICY tenant_scope ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true))', name);
  END LOOP;
  FOREACH name IN ARRAY ARRAY['bindings','builds','citations'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', name);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', name);
    EXECUTE format('DROP POLICY IF EXISTS kb_scope ON %I', name);
    EXECUTE format('CREATE POLICY kb_scope ON %I USING (tenant_id = current_setting(''app.tenant_id'', true) AND kb_id = current_setting(''app.kb_id'', true)) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true) AND kb_id = current_setting(''app.kb_id'', true))', name);
  END LOOP;
END $$;
GRANT USAGE ON SCHEMA __DATABASE_SCHEMA__ TO __DATABASE_RUNTIME_ROLE__;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA __DATABASE_SCHEMA__ TO __DATABASE_RUNTIME_ROLE__;
REVOKE UPDATE, DELETE ON source_versions, parse_snapshots, citations FROM __DATABASE_RUNTIME_ROLE__;
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS pg_textsearch WITH SCHEMA public;
CREATE SCHEMA IF NOT EXISTS __DATABASE_SCHEMA__;
REVOKE ALL ON SCHEMA __DATABASE_SCHEMA__ FROM PUBLIC;
GRANT USAGE ON SCHEMA __DATABASE_SCHEMA__ TO __DATABASE_RUNTIME_ROLE__;
CREATE TABLE IF NOT EXISTS __DATABASE_SCHEMA__.search_generations (
  index_name text PRIMARY KEY, tenant_id text NOT NULL, kb_id text NOT NULL,
  dimension integer, unit_count integer NOT NULL, units_sha256 text NOT NULL,
  ready boolean NOT NULL DEFAULT false, seal text
);
ALTER TABLE __DATABASE_SCHEMA__.search_generations ENABLE ROW LEVEL SECURITY;
ALTER TABLE __DATABASE_SCHEMA__.search_generations FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS search_scope ON __DATABASE_SCHEMA__.search_generations;
CREATE POLICY search_scope ON __DATABASE_SCHEMA__.search_generations USING
 (tenant_id=current_setting('app.tenant_id',true) AND kb_id=current_setting('app.kb_id',true));
REVOKE INSERT,UPDATE,DELETE ON __DATABASE_SCHEMA__.search_generations FROM __DATABASE_RUNTIME_ROLE__;
GRANT SELECT ON __DATABASE_SCHEMA__.search_generations TO __DATABASE_RUNTIME_ROLE__;

CREATE OR REPLACE FUNCTION __DATABASE_SCHEMA__.search_scope(p_index text)
RETURNS TABLE(tenant_id text,kb_id text) LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, __DATABASE_SCHEMA__ AS $$
 SELECT tenant_id,kb_id FROM __DATABASE_SCHEMA__.search_generations WHERE index_name=p_index;
$$;
REVOKE ALL ON FUNCTION __DATABASE_SCHEMA__.search_scope(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION __DATABASE_SCHEMA__.search_scope(text) TO __DATABASE_RUNTIME_ROLE__;

CREATE OR REPLACE FUNCTION __DATABASE_SCHEMA__.create_search_generation(p_index text, p_dimension integer, p_count integer, p_sha text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog,__DATABASE_SCHEMA__ AS $$
DECLARE suffix text; tab text; tenant text := current_setting('app.tenant_id'); kb text := current_setting('app.kb_id');
BEGIN
 IF tenant='' OR kb='' OR p_index !~ '^kb-[0-9a-f]{24}-[0-9a-f]{32}$' OR p_count<1
    OR (p_dimension IS NOT NULL AND (p_dimension<1 OR p_dimension>16000)) THEN
   RAISE EXCEPTION 'Invalid search generation';
 END IF;
 INSERT INTO __DATABASE_SCHEMA__.search_generations VALUES (p_index,tenant,kb,p_dimension,p_count,p_sha,false,NULL);
 FOREACH suffix IN ARRAY ARRAY['b','p'] LOOP
   tab := 'g_' || md5(p_index) || '_' || suffix;
   EXECUTE format('CREATE TABLE __DATABASE_SCHEMA__.%I (rowid bigint PRIMARY KEY, unit_id text UNIQUE NOT NULL,
     tenant_id text NOT NULL CHECK(tenant_id=%L), kb_id text NOT NULL CHECK(kb_id=%L),
     binding_key text NOT NULL, kind text NOT NULL, citation_id text NOT NULL,
     data jsonb NOT NULL, embedding public.vector, body text NOT NULL, exact text NOT NULL, heading text NOT NULL)',tab,tenant,kb);
   EXECUTE format('ALTER TABLE __DATABASE_SCHEMA__.%I ENABLE ROW LEVEL SECURITY',tab);
   EXECUTE format('ALTER TABLE __DATABASE_SCHEMA__.%I FORCE ROW LEVEL SECURITY',tab);
   EXECUTE format('CREATE POLICY scope ON __DATABASE_SCHEMA__.%I USING (tenant_id=current_setting(''app.tenant_id'',true) AND kb_id=current_setting(''app.kb_id'',true))',tab);
   EXECUTE format('GRANT SELECT,INSERT ON __DATABASE_SCHEMA__.%I TO %I',tab,session_user);
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION __DATABASE_SCHEMA__.create_search_generation(text,integer,integer,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION __DATABASE_SCHEMA__.create_search_generation(text,integer,integer,text) TO __DATABASE_RUNTIME_ROLE__;

CREATE OR REPLACE FUNCTION __DATABASE_SCHEMA__.finish_search_generation(p_index text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,__DATABASE_SCHEMA__ AS $$
DECLARE suffix text; tab text; field text; generation __DATABASE_SCHEMA__.search_generations; total bigint:=0; n bigint;
BEGIN
 SELECT * INTO STRICT generation FROM __DATABASE_SCHEMA__.search_generations WHERE index_name=p_index
   AND tenant_id=current_setting('app.tenant_id') AND kb_id=current_setting('app.kb_id') FOR UPDATE;
 IF generation.ready THEN RAISE EXCEPTION 'Generation is immutable'; END IF;
 FOREACH suffix IN ARRAY ARRAY['b','p'] LOOP
   tab := 'g_' || md5(p_index) || '_' || suffix;
   EXECUTE format('SELECT count(*) FROM __DATABASE_SCHEMA__.%I',tab) INTO n;
   total := total+n;
   FOREACH field IN ARRAY ARRAY['body','exact','heading'] LOOP
     EXECUTE format('CREATE INDEX %I ON __DATABASE_SCHEMA__.%I USING bm25 (%I) WITH (text_config=''simple'')',tab||'_'||field,tab,field);
   END LOOP;
   EXECUTE format('CREATE INDEX ON __DATABASE_SCHEMA__.%I (binding_key)',tab);
   EXECUTE format('REVOKE INSERT ON __DATABASE_SCHEMA__.%I FROM %I',tab,session_user);
   EXECUTE format('ANALYZE __DATABASE_SCHEMA__.%I',tab);
 END LOOP;
 IF total<>generation.unit_count THEN RAISE EXCEPTION 'Generation count mismatch'; END IF;
 UPDATE __DATABASE_SCHEMA__.search_generations SET ready=true WHERE index_name=p_index;
END $$;
REVOKE ALL ON FUNCTION __DATABASE_SCHEMA__.finish_search_generation(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION __DATABASE_SCHEMA__.finish_search_generation(text) TO __DATABASE_RUNTIME_ROLE__;

CREATE OR REPLACE FUNCTION __DATABASE_SCHEMA__.seal_search_generation(p_index text,p_seal text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,__DATABASE_SCHEMA__ AS $$
BEGIN
 UPDATE __DATABASE_SCHEMA__.search_generations SET seal=p_seal WHERE index_name=p_index AND ready
  AND tenant_id=current_setting('app.tenant_id') AND kb_id=current_setting('app.kb_id')
  AND (seal IS NULL OR seal=p_seal);
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing or differently sealed generation'; END IF;
END $$;
REVOKE ALL ON FUNCTION __DATABASE_SCHEMA__.seal_search_generation(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION __DATABASE_SCHEMA__.seal_search_generation(text,text) TO __DATABASE_RUNTIME_ROLE__;

CREATE TABLE IF NOT EXISTS __DATABASE_SCHEMA__.search_manifests (
 tenant_id text NOT NULL, kb_id text NOT NULL, manifest jsonb NOT NULL, checksum text NOT NULL,
 PRIMARY KEY(tenant_id,kb_id)
);
ALTER TABLE __DATABASE_SCHEMA__.search_manifests ENABLE ROW LEVEL SECURITY;
ALTER TABLE __DATABASE_SCHEMA__.search_manifests FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS manifest_scope ON __DATABASE_SCHEMA__.search_manifests;
CREATE POLICY manifest_scope ON __DATABASE_SCHEMA__.search_manifests USING
 (tenant_id=current_setting('app.tenant_id',true) AND kb_id=current_setting('app.kb_id',true));
GRANT SELECT,INSERT,UPDATE ON __DATABASE_SCHEMA__.search_manifests TO __DATABASE_RUNTIME_ROLE__;
CREATE TABLE IF NOT EXISTS embedding_jobs (
 tenant_id text NOT NULL, kb_id text NOT NULL, build_id text NOT NULL,
 batch_no integer NOT NULL, dependency_hash text NOT NULL, provider_hash text NOT NULL,
 payload jsonb NOT NULL, status text NOT NULL DEFAULT 'PENDING'
 CHECK (status IN ('PENDING','RUNNING','COMPLETE','RETRY','ERROR','UNKNOWN')),
 attempt integer NOT NULL DEFAULT 0, request_id text, lease_until timestamptz,
 retry_at timestamptz, vectors jsonb, vectors_hash text, error text,
 PRIMARY KEY (tenant_id,kb_id,build_id,batch_no)
);
CREATE TABLE IF NOT EXISTS embedding_attempts (
 tenant_id text NOT NULL, kb_id text NOT NULL, build_id text NOT NULL,
 batch_no integer NOT NULL, request_id text NOT NULL,
 status text NOT NULL CHECK (status IN ('RUNNING','COMPLETE','ERROR','UNKNOWN')),
 diagnostic text, created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY (tenant_id,kb_id,request_id)
);
CREATE TABLE IF NOT EXISTS embedding_circuits (
 tenant_id text NOT NULL, kb_id text NOT NULL, provider_hash text NOT NULL,
 failures integer NOT NULL DEFAULT 0, open_until timestamptz,
 PRIMARY KEY (tenant_id,kb_id,provider_hash)
);
DO $$ DECLARE name text; BEGIN
 FOREACH name IN ARRAY ARRAY['embedding_jobs','embedding_attempts','embedding_circuits'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', name);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', name);
  EXECUTE format('DROP POLICY IF EXISTS kb_scope ON %I', name);
  EXECUTE format('CREATE POLICY kb_scope ON %I USING (tenant_id = current_setting(''app.tenant_id'', true) AND kb_id = current_setting(''app.kb_id'', true)) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true) AND kb_id = current_setting(''app.kb_id'', true))', name);
  EXECUTE format('GRANT SELECT, INSERT, UPDATE ON %I TO __DATABASE_RUNTIME_ROLE__', name);
 END LOOP;
END $$;
